static int length(char*s){int n;n=0;while(s[n])n=n+1;return n;}
int wildcard_match(char*text,char*pattern){int previous[128];int current[128];int text_length;int pattern_length;int i;int j;text_length=length(text);pattern_length=length(pattern);for(j=0;j<=text_length;j=j+1)previous[j]=0;previous[0]=1;for(i=1;i<=pattern_length;i=i+1){current[0]=previous[0]&&pattern[i-1]=='*';for(j=1;j<=text_length;j=j+1){if(pattern[i-1]=='*')current[j]=current[j-1]||previous[j];else current[j]=previous[j-1]&&(pattern[i-1]=='?'||pattern[i-1]==text[j-1]);}for(j=0;j<=text_length;j=j+1)previous[j]=current[j];}return previous[text_length];}
int main(void){if(wildcard_match("aa","a"))return 1;if(!wildcard_match("aa","*"))return 2;if(wildcard_match("cb","?a"))return 3;if(!wildcard_match("adceb","*a*b"))return 4;if(wildcard_match("acdcb","a*c?b"))return 5;return 42;}
